    ('course-bili-bv17t4y1c7za', 'course-bili-bv17t4y1c7za', '100001', '0', 'BILI-FIN-002', 'course-category-finance', 'instructor-bili-383587023', '财务报表分析【全59课】国家精品课程', '59 讲完整课程 · 10 小时 16 分钟', '财务报表分析【全59课】国家精品课程。共 59 讲，累计 10.3 小时，由 复利的奇迹价值投资 讲解，章节结构完整，可直接在课程播放器中观看。', '张新民、钱爱民编著，中国人民大学出版社，2019年8月版；2、《财务报表分析（第五版）案例分析与学习指导》，钱爱民、张新民编著，中国人民大学出版社，2020年1月版；3、《财务报表分析案例（第二版》，张新民、钱爱民编著，中国人民大学出版社，2019年7月版；3、《从报表看企业-数字背后的秘密（第三版）》，中国人民大学出版社，2017年5月版；阅读和分析企业财务报表，是商科各专业学生必备的核心专业技能之一，也是商学院（或管理学院、经济管理学院等）开设的一门重要课程。本课程以案例为依托，旨在为学生打下良好的理论基础，同时保证知识的时效性和实用性。与其他同类课程相比，本课程具有三个特点： 首先，财务报表分析框架独具特色，分析方法体系更加完善。本课程围绕主讲人提出的“企业财务状况质量分析理论”来构建财务报表分析框架，并将最新的研究成果融入相关章节，从而使得本课程的财务报表分析内容独具特色屏自成体系。本课程大量采用上市公司真实案例，使分析内容具有高度的时效性和实用性。本课程既对综合案例（如格力电器案例）进行分析，又在授课过程中针对具体分析项目添加了大量的小案例，内容更加鲜活，解释更加清晰，针对 课程结构：共 8 章 59 讲，累计时长 10 小时 16 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立个人与家庭的财务规划框架","理解基金、股票、债券等常见资产的风险收益特征","掌握财报阅读与基本面分析的基本方法","形成可执行的资产配置与风险管理习惯"]', '["希望系统学习理财的零基础人群","需要读懂财报的职场人与创业者","金融专业在校学生"]', '["具备基础数学计算能力","无需金融从业背景"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/34976781fedef9862e85f52a31265c0e914bc709.jpg', '["金融财经","投资理财","财务知识","对外经济贸易大学","财务报表分析","全59课"]', 36990, 59, 260654, '4.4', 85761, 'BV17T4y1C7za', NULL, NULL, NULL, 1, 0, 'standard', NULL, '复利的奇迹价值投资', 0, 'tenant', 'published', '2022-02-07T07:30:44.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
