VALUES
    ('course-bili-season-6872237', 'course-bili-season-6872237', '100001', '0', 'BILI-FIN-003', 'course-category-finance', 'instructor-bili-383587023', '股票投资课程！', '26 讲完整课程 · 193 小时 29 分钟', '本视频课程是徐高博士在北京大学国家发展研究院2019年春开设的“金融经济学”课程实录。该课程是徐高博士数年来精心打造的精品课程，备受北大学子追捧，被认为是“最好的金融经济学课程”之一；该课程配套的教材《金融经济学二十五讲', '课程简介：本视频课程是徐高博士在北京大学国家发展研究院2019年春开设的“金融经济学”课程实录。该课程是徐高博士数年来精心打造的精品课程，备受北大学子追捧，被认为是“最好的金融经济学课程”之一；该课程配套的教材《金融经济学二十五讲》也于2018年由中国人民大学出版社出版（配套使用，效果更佳） 课程结构：共 1 章 26 讲，累计时长 193 小时 29 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立个人与家庭的财务规划框架","理解基金、股票、债券等常见资产的风险收益特征","掌握财报阅读与基本面分析的基本方法","形成可执行的资产配置与风险管理习惯"]', '["希望系统学习理财的零基础人群","需要读懂财报的职场人与创业者","金融专业在校学生"]', '["具备基础数学计算能力","无需金融从业背景"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/e0510f3fa88e1005e5dcba0fce6ce724ab8ac639.jpg', '["金融财经","投资理财","财务知识","股票投资课程！"]', 696591, 26, 274483, '4.4', 62042, 'BV1fgByYtEfc', NULL, NULL, NULL, 1, 0, 'standard', NULL, '复利的奇迹价值投资', 0, 'tenant', 'published', '2024-11-24T04:51:59.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
