-- ── BILI-FIN-021 · 《大学生普通人金融理财入门学习手册》™B站版 ──

INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-6531883', 'course-bili-season-6531883', '100001', '0', 'BILI-FIN-021', 'course-category-finance', 'instructor-bili-109187896', '《大学生普通人金融理财入门学习手册》™B站版', '16 讲完整课程 · 6 小时 9 分钟', '这个视频的文字稿+Excalidraw上展示的文案至少两万字。一篇超级硬核的科普+投资本质分享，证明一下我确实是知识区up主。很多大学生（甚至包括塑料叉）对理财的知识都一无所知。我的一个好朋友，无论是绩点还是科研还是实', '课程简介：这个视频的文字稿+Excalidraw上展示的文案至少两万字。一篇超级硬核的科普+投资本质分享，证明一下我确实是知识区up主。很多大学生（甚至包括塑料叉）对理财的知识都一无所知。我的一个好朋友，无论是绩点还是科研还是实习都能稳抓的同时，却对理财一窍不通，表示自己完全不懂和钱相关的内容，仿佛这是什么非常危险的赌场（当然它可以是）。我想要改变和更正一些人对金融，对投资的看法。市场不应该是他们理解的那样，我也不希望有人在里面赌博。有很多人在面对市面上如此繁杂，难以区分的信息的时候，又困于找不到一条合适的学习路线。我想要用一个视频给大家讲清楚所有理财的本质，后续如果反响不错（点赞过万），我就接着做下一期。纯粹的为爱发电，但是做出有价值的内容也是我和观众共同的追求。理财“祛魅”，我不希望别人对理财二字有什么偏见，我更希望的是进入市场的新人们能找到自己合适的，试错并不可怕，但是方向一定要对。在时代的大变革下，希望我们都能一生“富一次”。讲义和文案需要的话，点点赞啊投投币啊；） 课程结构：共 1 章 16 讲，累计时长 6 小时 9 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立个人与家庭的财务规划框架","理解基金、股票、债券等常见资产的风险收益特征","掌握财报阅读与基本面分析的基本方法","形成可执行的资产配置与风险管理习惯"]', '["希望系统学习理财的零基础人群","需要读懂财报的职场人与创业者","金融专业在校学生"]', '["具备基础数学计算能力","无需金融从业背景"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/abf89862cc256fa4e726a5b7376fa46e235c077b.jpg', '["金融财经","投资理财","财务知识","投资","™B站版"]', 22152, 16, 160320, '4.8', 72207, 'BV1tj6wBDEXF', NULL, NULL, NULL, 1, 0, 'standard', NULL, '朝阳不吐不快', 0, 'tenant', 'published', '2026-01-29T12:40:09.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
