VALUES
    ('course-bili-bv1kj411q7h6', 'course-bili-bv1kj411q7h6', '100001', '0', 'BILI-FIN-023', 'course-category-finance', 'instructor-bili-374894977', '人人有用的零基础理财入门课（完结）', '20 讲完整课程 · 9 小时 1 分钟', '唯库 这套人人可入门、人人可实践的理财课程，将彻底改变你的观念，提升你的生活品质，让理财成为一种习惯。零基础不要紧，她将带你从零开始，大步昂扬靠近最梦想的生活！但梦想不该永远只是想象。无论你月薪一千还是一千万', '课程简介：唯库 这套人人可入门、人人可实践的理财课程，将彻底改变你的观念，提升你的生活品质，让理财成为一种习惯。零基础不要紧，她将带你从零开始，大步昂扬靠近最梦想的生活！但梦想不该永远只是想象。无论你月薪一千还是一千万，现在就朝着财富自由，大步出发吧！课程结构：共 3 章 20 讲，累计时长 9 小时 1 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立个人与家庭的财务规划框架","理解基金、股票、债券等常见资产的风险收益特征","掌握财报阅读与基本面分析的基本方法","形成可执行的资产配置与风险管理习惯"]', '["希望系统学习理财的零基础人群","需要读懂财报的职场人与创业者","金融专业在校学生"]', '["具备基础数学计算能力","无需金融从业背景"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/773a4d61e3bee30e4d57cf61e8200982f9c15abe.jpg', '["金融财经","投资理财","财务知识","完结"]', 32490, 20, 23242, '4.4', 6446, 'BV1KJ411Q7H6', NULL, NULL, NULL, 1, 0, 'standard', NULL, '建筑室内设计', 0, 'tenant', 'published', '2019-11-29T08:47:35.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
