VALUES
    ('course-bili-bv15x411f7el', 'course-bili-bv15x411f7el', '100001', '0', 'BILI-FIN-040', 'course-category-finance', 'instructor-bili-439028291', '北京大学 · 会计学基础（43课全）', '45 讲完整课程 · 8 小时 30 分钟', '北京大学光华管理学院会计系副教授 课程详情： 会计是一门商业语言，它把商业活动中的价值交换，忠实地记录下来，', '北京大学光华管理学院会计系副教授 课程详情： 会计是一门商业语言，它把商业活动中的价值交换，忠实地记录下来，转化为会计的报告。既要言词达意，又要让读者有效理解。记录企业的资金运动，揭示资金缺口，帮助企业应对变化。学习会计语言，就能读懂企业这本书。课程结构：共 6 章 45 讲，累计时长 8 小时 30 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立个人与家庭的财务规划框架","理解基金、股票、债券等常见资产的风险收益特征","掌握财报阅读与基本面分析的基本方法","形成可执行的资产配置与风险管理习惯"]', '["希望系统学习理财的零基础人群","需要读懂财报的职场人与创业者","金融专业在校学生"]', '["具备基础数学计算能力","无需金融从业背景"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/cd4363e72836fe03421769b03d467eb4396cae49.jpg', '["金融财经","投资理财","财务知识","【公开课】北京大学","会计学基础（43课全）"]', 30658, 45, 1144897, '4.5', 309984, 'BV15x411f7eL', NULL, NULL, NULL, 1, 0, 'standard', NULL, 'WU_Eric', 0, 'tenant', 'published', '2019-07-10T11:15:16.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
